  {
    "statement": "The evidence suggests that leaving uncut strips of rye grass provides clearer benefits for seed-eating birds.",
    "citations": []
  },
  {
    "statement": "Raising the mowing height shows mixed and less consistent results for wildlife benefits in UK grasslands.",
    "citations": []
  }
]

